mapper.select:
SELECT T1.INDENTIFY_MARK AS indentifyMark, T1.ORG_INDENTIFY_MARK AS orgIndentifyMark, T1.REGIST_BANK_CODE AS bankCode, T1.IS_BELONG_BANK AS isBelongBank, T1.THE_BANK_NAME AS theBankName, T1.THE_BANK_CODE AS theBankCode, T1.HOLDER_MARK AS holderMark, T1.HOLDER_REGION AS holderRegion, T1.HOLDER_TYPE AS holderType, T1.PERSONAL_IDENTIFY_TYPE AS personalIdentifyType, T1.INSTITUTION_IDENTIFY_TYPE AS institutionIdentifyType, T1.OTHER_IDENTIFY_NAME AS otherIdentifyName, T1.IDENTIFY_NUMBER AS identifyNumber, T1.SPV_CAP_ACC_BANK AS spvCapAccBank, T1.OTHER_CAP_ACC_BANK AS otherCapAccBank, T1.SPV_REGIST_CODE AS spvRegistCode, T1.HOLDER_DATE AS holderDate, T1.HOLDER_NAME AS holderName, T1.HOLDER_SEX AS holderSex, T1.HOLDER_RISK_PREFER AS holderRiskPrefer, T1.HOLDER_CELLPHONE AS holderCellphone, T1.HOLDER_TELEPHONE AS holderTelephone, T1.HOLDER_EMAIL AS holderEmail, T1.REMARK AS remark, T1.STATUS AS status, T1.DEPT_CODE AS deptCode, T1.UPDATE_USER AS updateUser, T1.UPDATE_TIME AS updateTime, T1.CREATE_USER AS createUser, T1.ORG_CODE AS orgCode from chb_equ_sub T1 inner join chb_equ_hold th on th.INDENTIFY_MARK=T1.INDENTIFY_MARK and ifnull(th.ORG_INDENTIFY_MARK,'0')=ifnull(T1.ORG_INDENTIFY_MARK,'0') left join CHB_SUBMIT_STATUS t2 on t1.SUMIT_SEQ = t2.SEQNO
(t2.SUBMIT_FEEDBACK_STATUS = '03' or T1.ORG_INDENTIFY_MARK is not null)
t1.REGIST_BANK_CODE = #{item.REGIST_BANK_CODE,jdbcType=VARCHAR} and t1.IDENTIFY_NUMBER = #{item.IDENTIFY_NUMBER,jdbcType=VARCHAR} and t1.HOLDER_NAME = #{item.HOLDER_NAME,jdbcType=VARCHAR}
and t1.PERSONAL_IDENTIFY_TYPE = #{item.PERSONAL_IDENTIFY_TYPE,jdbcType=VARCHAR}
and t1.INSTITUTION_IDENTIFY_TYPE = #{item.INSTITUTION_IDENTIFY_TYPE,jdbcType=VARCHAR}
and t1.OTHER_IDENTIFY_NAME = #{item.OTHER_IDENTIFY_NAME,jdbcType=VARCHAR}

SELECT T1.INDENTIFY_MARK AS indentifyMark, T1.ORG_INDENTIFY_MARK AS orgIndentifyMark, T1.REGIST_BANK_CODE AS bankCode, T1.IS_BELONG_BANK AS isBelongBank, T1.THE_BANK_NAME AS theBankName, T1.THE_BANK_CODE AS theBankCode, T1.HOLDER_MARK AS holderMark, T1.HOLDER_REGION AS holderRegion, T1.HOLDER_TYPE AS holderType, T1.PERSONAL_IDENTIFY_TYPE AS personalIdentifyType, T1.INSTITUTION_IDENTIFY_TYPE AS institutionIdentifyType, T1.OTHER_IDENTIFY_NAME AS otherIdentifyName, T1.IDENTIFY_NUMBER AS identifyNumber, T1.SPV_CAP_ACC_BANK AS spvCapAccBank, T1.OTHER_CAP_ACC_BANK AS otherCapAccBank, T1.SPV_REGIST_CODE AS spvRegistCode, T1.HOLDER_DATE AS holderDate, T1.HOLDER_NAME AS holderName, T1.HOLDER_SEX AS holderSex, T1.HOLDER_RISK_PREFER AS holderRiskPrefer, T1.HOLDER_CELLPHONE AS holderCellphone, T1.HOLDER_TELEPHONE AS holderTelephone, T1.HOLDER_EMAIL AS holderEmail, T1.REMARK AS remark, T1.STATUS AS status, T1.DEPT_CODE AS deptCode, T1.UPDATE_USER AS updateUser, T1.UPDATE_TIME AS updateTime, T1.CREATE_USER AS createUser, T1.ORG_CODE AS orgCode from chb_equ_sub T1 left join CHB_SUBMIT_STATUS t2 on t1.SUMIT_SEQ = t2.SEQNO where (t2.SUBMIT_FEEDBACK_STATUS = '03' or T1.ORG_INDENTIFY_MARK is not null)
AND concat_ws ('',T1.REGIST_BANK_CODE ,'_',T1.IDENTIFY_NUMBER ,'_',T1.HOLDER_NAME ,'_',T1.PERSONAL_IDENTIFY_TYPE ,'_',T1.INSTITUTION_IDENTIFY_TYPE ,'_',T1.OTHER_IDENTIFY_NAME) IN
#{key,jdbcType=VARCHAR}

SELECT * FROM ( SELECT ifnull(( SELECT T.INDENTIFY_MARK FROM CHB_EQU_SUB T WHERE T.ORG_INDENTIFY_MARK = T1.INDENTIFY_MARK AND STATUS != '03' LIMIT 1 ), T1.INDENTIFY_MARK ) AS indentifyMark, T1.ORG_INDENTIFY_MARK AS orgIndentifyMark, T1.REGIST_BANK_CODE AS bankCode, T1.IS_BELONG_BANK AS isBelongBank, T1.THE_BANK_NAME AS theBankName, T1.THE_BANK_CODE AS theBankCode, T1.HOLDER_MARK AS holderMark, T1.HOLDER_REGION AS holderRegion, T1.HOLDER_TYPE AS holderType, T1.PERSONAL_IDENTIFY_TYPE AS personalIdentifyType, T1.INSTITUTION_IDENTIFY_TYPE AS institutionIdentifyType, T1.OTHER_IDENTIFY_NAME AS otherIdentifyName, T1.IDENTIFY_NUMBER AS identifyNumber, T1.SPV_CAP_ACC_BANK AS spvCapAccBank, T1.OTHER_CAP_ACC_BANK AS otherCapAccBank, T1.SPV_REGIST_CODE AS spvRegistCode, T1.HOLDER_DATE AS holderDate, T1.HOLDER_NAME AS holderName, T1.HOLDER_SEX AS holderSex, T1.HOLDER_RISK_PREFER AS holderRiskPrefer, T1.HOLDER_CELLPHONE AS holderCellphone, T1.HOLDER_TELEPHONE AS holderTelephone, T1.HOLDER_EMAIL AS holderEmail, T1.REMARK AS remark, T1.STATUS AS STATUS, T1.DEPT_CODE AS deptCode, T1.UPDATE_USER AS updateUser, T1.UPDATE_TIME AS updateTime, T1.CREATE_USER AS createUser, T1.ORG_CODE AS orgCode, IF ( ( @group1 = T1.gg ), @rank := @rank + 1, @rank := 1 ) AS rank, @group1 := T1.gg FROM /* 定义临时变量池 */ ( SELECT @rownum := 0, @group1 := NULL, @rank := 0 ) a, ( SELECT tmp.*, concat_ws( '', tmp.REGIST_BANK_CODE, '_', tmp.IDENTIFY_NUMBER, '_', tmp.HOLDER_NAME, '_', tmp.PERSONAL_IDENTIFY_TYPE, '_', tmp.INSTITUTION_IDENTIFY_TYPE, '_', tmp.OTHER_IDENTIFY_NAME ) gg FROM chb_view_equ_sub tmp ORDER BY update_time DESC ) T1 INNER JOIN CHB_SUBMIT_STATUS t2 ON t1.SUMIT_SEQ = t2.SEQNO
t2.SUBMIT_FEEDBACK_STATUS = '03' AND concat_ws('',t1.REGIST_BANK_CODE, '_', t1.IDENTIFY_NUMBER, '_', t1.HOLDER_NAME, '_', t1.PERSONAL_IDENTIFY_TYPE,, '_', t1.INSTITUTION_IDENTIFY_TYPE, '_', t1.OTHER_IDENTIFY_NAME) = #{key,jdbcType=VARCHAR}
) where rank = 1

SELECT s1.* FROM CHB_EQU_HOLD s1 INNER join ( SELECT count(1),ch.REGIST_BANK_CODE,ch.PERSONAL_IDENTIFY_TYPE, ch.INSTITUTION_IDENTIFY_TYPE,ch.OTHER_IDENTIFY_NAME,ch.IDENTIFY_NUMBER,ch.HOLDER_NAME FROM CHB_EQU_HOLD ch INNER join CHB_equ_SUB cs ON ch.INDENTIFY_MARK=cs.INDENTIFY_MARK and ch.REGIST_BANK_CODE=cs.REGIST_BANK_CODE WHERE cs.SUBMIT_STATUS ='01' group by ch.REGIST_BANK_CODE, ch.PERSONAL_IDENTIFY_TYPE, ch.INSTITUTION_IDENTIFY_TYPE, ch.OTHER_IDENTIFY_NAME, ch.IDENTIFY_NUMBER, ch.HOLDER_NAME having count(1)>1 ) s2 on s1.REGIST_BANK_CODE=s2.REGIST_BANK_CODE and (s1.PERSONAL_IDENTIFY_TYPE=s2.PERSONAL_IDENTIFY_TYPE or(s1.PERSONAL_IDENTIFY_TYPE is null and s2.PERSONAL_IDENTIFY_TYPE is null )) and (s1.INSTITUTION_IDENTIFY_TYPE=s2.INSTITUTION_IDENTIFY_TYPE or(s1.INSTITUTION_IDENTIFY_TYPE is null and s2.INSTITUTION_IDENTIFY_TYPE is null )) and (s1.OTHER_IDENTIFY_NAME=s2.OTHER_IDENTIFY_NAME or(s1.OTHER_IDENTIFY_NAME is null and s2.OTHER_IDENTIFY_NAME is null )) and s1.IDENTIFY_NUMBER=s2.IDENTIFY_NUMBER and s1.HOLDER_NAME=s2.HOLDER_NAME where s1.status='E'
AND concat_ws('',s1.REGIST_BANK_CODE, '_', s1.IDENTIFY_NUMBER, '_', s1.HOLDER_NAME, '_', s1.PERSONAL_IDENTIFY_TYPE,, '_', s1.INSTITUTION_IDENTIFY_TYPE, '_', s1.OTHER_IDENTIFY_NAME) IN
#{key,jdbcType=VARCHAR}

select INDENTIFY_MARK as indentifyMark, ORG_INDENTIFY_MARK as orgIndentifyMark, REGIST_BANK_CODE as bankCode, IS_BELONG_BANK as isBelongBank, THE_BANK_NAME as theBankName, THE_BANK_CODE as theBankCode, HOLDER_MARK as holderMark, HOLDER_REGION as holderRegion, HOLDER_TYPE as holderType, ifnull(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE) identifyType, PERSONAL_IDENTIFY_TYPE as personalIdentifyType, INSTITUTION_IDENTIFY_TYPE as institutionIdentifyType, ifnull(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE) as IDENTIFY_TYPE, OTHER_IDENTIFY_NAME as otherIdentifyName, IDENTIFY_NUMBER as identifyNumber, SPV_CAP_ACC_BANK as spvCapAccBank, OTHER_CAP_ACC_BANK as otherCapAccBank, SPV_REGIST_CODE as spvRegistCode, HOLDER_DATE holderDate, HOLDER_NAME holderName, HOLDER_SEX holderSex, HOLDER_RISK_PREFER as holderRiskPrefer, HOLDER_CELLPHONE as holderCellphone, HOLDER_TELEPHONE as holderTelephone, HOLDER_EMAIL as holderEmail, TYPE as type, REMARK as remark, SUBMIT_STATUS as submitStatus, SUBMIT_TIME as submitTime, CHB_SUBMIT_DEADLINE as chbSubmitDeadline, SUBMIT_DEADLINE as submitDeadline, STATUS as status, UPDATE_TIME as updateTime, SUMIT_SEQ as sumitSeq, ORG_CODE as orgCode, CHECK_SEQNO as checkSeqno from CHB_EQU_SUB where SUBMIT_STATUS='01'
AND concat_ws('',REGIST_BANK_CODE, '_', INDENTIFY_MARK) IN
#{key,jdbcType=VARCHAR}
